import {SamplePlayer} from './sample-player.js';
export class AudioEngine{
 constructor(){this.ctx=null;this.voices=new Set();this.melodyVolume=.65;this.metalTone='compas';this.tutorialPitch='score';this.metroVolume=.35;this.muted=false;this.metroOn=true;this.recordMetro=true;}
 async init(){if(!this.ctx){this.ctx=new AudioContext();this.out=this.ctx.createGain();this.out.gain.value=.45;this.limiter=this.ctx.createDynamicsCompressor();this.limiter.threshold.value=-10;this.limiter.ratio.value=8;this.out.connect(this.limiter);this.limiter.connect(this.ctx.destination);this.capture=this.ctx.createMediaStreamDestination();this.limiter.connect(this.capture);this.metro=this.ctx.createGain();this.metro.connect(this.ctx.destination);this.metroRecord=this.ctx.createGain();this.metro.connect(this.metroRecord);this.metroRecord.connect(this.capture);this.samples=new SamplePlayer(this.ctx,this.voices);}await this.ctx.resume();}
 cancel(){for(const o of this.voices){try{o.stop();}catch{}}this.voices.clear();this.samples?.clear();}
 tone(freq,when,duration,gain,bus,type='sine'){
  const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.0001,when);g.gain.exponentialRampToValueAtTime(Math.max(.0001,gain),when+.003);g.gain.exponentialRampToValueAtTime(.0001,when+duration);o.connect(g);g.connect(bus);o.start(when);o.stop(when+duration+.01);this.voices.add(o);o.onended=()=>{this.voices.delete(o);o.disconnect();g.disconnect();};
 }
 sustain(freq,when,duration,gain,bus,type='sine',attack=.015){
  const o=this.ctx.createOscillator(),g=this.ctx.createGain(),d=Math.max(.03,duration),a=Math.min(attack,d*.4);o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.0001,when);g.gain.linearRampToValueAtTime(gain,when+a);g.gain.setValueAtTime(gain*.75,when+Math.max(a,d-.04));g.gain.exponentialRampToValueAtTime(.0001,when+d+.04);o.connect(g);g.connect(bus);o.start(when);o.stop(when+d+.05);this.voices.add(o);o.onended=()=>{this.voices.delete(o);o.disconnect();g.disconnect();};
 }
 setMelodyVolume(value){this.melodyVolume=Math.max(0,Math.min(2,Number(value)||0));if(this.melodyBus)this.melodyBus.gain.setTargetAtTime(this.muted?0:this.melodyVolume,this.ctx.currentTime,.01);}
 note(n,when){if(this.muted)return;if(!this.melodyBus){this.melodyBus=this.ctx.createGain();this.melodyBus.connect(this.out);}this.melodyBus.gain.setValueAtTime(this.melodyVolume,this.ctx.currentTime);const midi=this.tutorialPitch==='score'?(n.soundMidi??n.midi):n.midi;if(this.metalTone==='clear'){const f=440*2**((midi-69)/12),gain=(n.velocity??.75)*.32;this.tone(f,when,.8,gain,this.melodyBus);this.tone(f*3,when,.16,gain*.1,this.melodyBus);return;}this.samples.play({id:'tutorial',name:'Metalófono',sound:'bells',emphasizeFundamental:this.tutorialPitch==='instrument'},{...n,midi},when,Math.max(.08,n.duration??.8),this.melodyBus);}
 click(accent,when){if(!this.metroOn)return;this.metroRecord.gain.value=this.recordMetro?1:0;this.tone(accent?1400:950,when,.055,this.metroVolume*.23,this.metro);}
}
